SELECT id, customer_id, device, browser, started_at, country, FIRST_VALUE(country) IGNORE NULLS OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country, ROW_NUMBER() OVER (PARTITION BY device ORDER BY started_at DESC, id) AS seq_no, LAST_VALUE(country) IGNORE NULLS OVER w_running AS last_known_country, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at, id) AS event_seq, ROW_NUMBER() OVER (ORDER BY started_at, id) AS seq_no_2 FROM sessions WINDOW w_running AS (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
